const warehousePreviousRender=render,warehousePreviousDetail=detail;
let warehouseMovements=[],transferDraft={codes:'',destination:2};
function usableBox(id){const b=boxes.find(b=>b.id===assetIdKey(id));if(!b||!mediumAssets.some(a=>a.id===b.id)||b.qty<=0||b.analysis||b.blocked||b.awaitingPacking)throw Error('Caixa sem estoque disponível: '+id);return b}
function transferSelection(codes){const ids=codes.split(/[,;\r\n]+/).map(assetIdKey).filter(Boolean);if(!ids.length)throw Error('Escaneie ou digite pelo menos uma caixa.');if(new Set(ids).size!==ids.length)throw Error('Uma caixa aparece mais de uma vez.');return ids.map(usableBox)}
function transferBoxes(codes,destination){const selected=transferSelection(codes),loc=Number(destination);if(!Number.isInteger(loc)||loc<0||loc>=locations.length)throw Error('Destino inválido.');if(selected.some(b=>b.loc===loc))throw Error('Uma das caixas já está no destino. Remova-a do lote.');const movement={id:'MOV-'+String(warehouseMovements.length+1).padStart(3,'0'),type:'Transferência',at:new Date().toISOString(),items:selected.map(b=>({id:b.id,qty:b.qty,flavor:b.flavor,lot:b.lot,from:b.loc,to:loc,state:b.state}))};for(const b of selected)b.loc=loc;warehouseMovements.push(movement);log(`${movement.id}: ${selected.length} caixas → ${locations[loc]}. ${movement.items.map(i=>`${i.id}: ${i.qty} pops, origem ${locations[i.from]}`).join('; ')}. Estado preservado.`);return movement}
function transferPage(){return `<section class="notice">Escaneie as caixas que serão movidas juntas. O destino muda; a quantidade, lote, classificação e estado permanecem iguais.</section><form class="receipt-form panel" onsubmit="confirmTransfer(event)"><label>IDs das caixas<textarea id="transfer-codes" required placeholder="CX-001&#10;CX-002" oninput="transferDraft.codes=this.value;previewTransfer()">${esc(transferDraft.codes)}</textarea></label><p>Um código por linha ou separado por vírgulas. Leitor que preenche texto; câmera ainda não conectada.</p>${select('destination','Destino',locations,Number(transferDraft.destination))}<div class="actions"><button type="button" onclick="previewTransfer()">Conferir caixas</button></div><div id="transfer-preview"></div><p id="transfer-error" role="alert" class="receipt-error"></p><button class="primary" type="submit">Confirmar transferência do lote</button></form>`}
function previewTransfer(){const output=$('transfer-preview');try{const bs=transferSelection(transferDraft.codes);output.innerHTML=`<h2>${bs.length} caixas · ${bs.reduce((s,b)=>s+b.qty,0)} pops</h2>`+bs.map(b=>`<div class="row"><div><strong>${b.id} · ${esc(b.flavor)} · ${b.qty} pops</strong><small>${esc(locations[b.loc])} · ${esc(b.state)} · ${b.grade}${b.active?' · caixa de separação':''}</small></div></div>`).join('');$('transfer-error').textContent=''}catch(err){output.innerHTML='';$('transfer-error').textContent=transferDraft.codes?err.message:''}}
function confirmTransfer(e){e.preventDefault();transferDraft.destination=e.target.elements.destination.value;try{const m=transferBoxes(transferDraft.codes,transferDraft.destination);transferDraft.codes='';go('Transferir caixas');toast(`${m.items.length} caixas transferidas`)}catch(err){$('transfer-error').textContent=err.message}}
function setPickingBox(id){const b=usableBox(id);const other=boxes.find(x=>x.active&&x.qty>0&&x.id!==b.id&&x.flavor===b.flavor&&x.state===b.state);if(other)throw Error('Já existe uma caixa de separação para este sabor e estado: '+other.id+'. Encerre-a antes de abrir outra.');b.active=true;log(`${b.id} aberta para separação: ${b.flavor}, ${b.state}, ${b.qty} pops`);return b}
function stopPicking(id){const b=usableBox(id);if(!b.active)throw Error('Esta caixa não está em separação.');b.active=false;log(`${b.id}: separação encerrada; ${b.qty} pops mantidos na caixa.`)}
function withdrawPicking(id,rawQty,reason){const b=usableBox(id),qty=Number(rawQty);if(!b.active)throw Error('Abra esta caixa para separação antes de retirar.');if(!Number.isInteger(qty)||qty<=0||qty>b.qty)throw Error('Informe uma quantidade inteira entre 1 e o saldo disponível.');if(!String(reason||'').trim())throw Error('Informe a finalidade ou referência da retirada.');const before=b.qty;b.qty-=qty;if(!b.qty)b.active=false;const movement={id:'MOV-'+String(warehouseMovements.length+1).padStart(3,'0'),type:'Retirada',at:new Date().toISOString(),boxId:b.id,fillId:b.fillId||null,flavor:b.flavor,lot:b.lot,state:b.state,location:b.loc,qty,before,after:b.qty,reason:reason.trim()};warehouseMovements.push(movement);log(`${movement.id}: retirada ${qty} de ${b.id}; saldo ${b.qty}. ${reason.trim()}${!b.qty?' Caixa vazia disponível para reutilização.':''}`);return movement}
function pickingForm(id){const b=usableBox(id);if(!b.active){openForm('Abrir caixa de separação',`<p><strong>${b.id} · ${esc(b.flavor)}</strong></p><p>${b.qty} pops · ${esc(b.state)} · ${b.grade} · ${esc(locations[b.loc])}</p><p>Uma caixa ativa por sabor e estado. Nenhuma quantidade será retirada ao abrir.</p>`,()=>setPickingBox(id));return}openForm('Retirar de '+b.id,`<p>${esc(b.flavor)} · ${esc(b.state)} · saldo: <strong>${b.qty} pops</strong></p>`+input('qty','Quantidade retirada',1,'number')+input('reason','Finalidade / referência')+'<p>Retirada de demonstração, ainda sem pedido ou faturamento. Ao zerar, a caixa fica vazia e mantém seu histórico.</p>',d=>withdrawPicking(id,d.qty,d.reason))}
function endPickingForm(id){const b=usableBox(id);openForm('Encerrar separação',`<p>${b.id} continuará com ${b.qty} pops. Ela deixa de ser a caixa de separação, permitindo abrir outra do mesmo sabor e estado.</p>`,()=>stopPicking(id))}
function pickingPage(){const available=boxes.filter(b=>b.qty>0&&!b.analysis&&!b.blocked&&!b.awaitingPacking&&mediumAssets.some(a=>a.id===b.id));return `<div class="notice">Uma caixa de separação por sabor e estado. Caixas parciais de reserva continuam no estoque; só a caixa ativa permite retiradas.</div><section class="panel"><h2>Em separação</h2>${available.filter(b=>b.active).map(b=>`<div class="row"><div><strong>${esc(b.flavor)} · ${esc(b.state)}</strong><small>${b.id} · ${b.qty} pops · ${b.grade} · ${esc(locations[b.loc])}</small></div><div class="actions"><button class="primary" onclick="pickingForm('${b.id}')">Retirar</button><button onclick="endPickingForm('${b.id}')">Encerrar separação</button></div></div>`).join('')||'<p>Nenhuma caixa aberta.</p>'}</section><section class="panel"><h2>Abrir outra caixa</h2>${available.filter(b=>!b.active).map(b=>`<div class="row"><div><strong>${b.id} · ${esc(b.flavor)} · ${b.qty} pops</strong><small>${esc(b.state)} · ${b.grade} · ${esc(locations[b.loc])}</small></div><button onclick="pickingForm('${b.id}')">Abrir para separação</button></div>`).join('')||'<p>Sem caixas disponíveis.</p>'}</section><section class="panel"><h2>Últimas retiradas</h2>${warehouseMovements.filter(m=>m.type==='Retirada').slice().reverse().map(m=>`<div class="row"><div><strong>${m.boxId} · −${m.qty} pops · saldo ${m.after}</strong><small>${esc(m.reason)} · ${m.at.slice(0,10)} ${m.at.slice(11,16)} UTC</small></div></div>`).join('')||'<p>Nenhuma retirada nesta sessão.</p>'}</section>`}
detail=function(id){const b=boxes.find(b=>b.id===id);if(!b||b.analysis||b.blocked||b.awaitingPacking)return warehousePreviousDetail(id);if(!b.qty){mediumHistory(id);return}openForm(b.id+' · '+b.flavor,`<p>${b.qty} pops · ${b.grade} · ${esc(b.lot)}<br>${esc(locations[b.loc])} · ${esc(b.state)}</p><div class="actions"><button type="button" onclick="$('modal').close();transferDraft.codes='${id}';go('Transferir caixas')">Transferir</button><button type="button" onclick="$('modal').close();pickingForm('${id}')">${b.active?'Retirar':'Abrir separação'}</button><button type="button" onclick="$('modal').close();confirmBoxState('${id}')">Confirmar estado</button><button type="button" onclick="$('modal').close();mediumHistory('${id}')">Histórico</button>${b.inspectionIndex!=null?`<button type="button" onclick="$('modal').close();showLabels(${b.inspectionIndex})">Etiquetas</button>`:''}</div>`,()=>{})};
function changeBoxState(id,state){const b=usableBox(id);if(!states.includes(state))throw Error('Estado inválido.');if(b.active&&boxes.some(x=>x.id!==id&&x.active&&x.qty>0&&x.flavor===b.flavor&&x.state===state))throw Error('Já existe caixa de separação para este sabor no estado escolhido.');const old=b.state;b.state=state;log(`${id}: estado confirmado ${old} → ${state}. Local: ${locations[b.loc]}`)}
function confirmBoxState(id){const b=usableBox(id);openForm('Confirmar estado físico',select('state','Estado verificado',states,states.indexOf(b.state))+'<p>Confirme o estado real do produto; a localização por si só não confirma congelamento.</p>',d=>changeBoxState(id,states[+d.state]))}
render=function(){warehousePreviousRender();if(view==='Início')$('app').querySelector('.tiles').insertAdjacentHTML('beforeend','<button class="tile" onclick="go(\'Transferir caixas\')"><span>↔</span>Transferir caixas<small>Escanear e mover um lote de caixas</small></button><button class="tile" onclick="go(\'Separação\')"><span>▣</span>Caixa de separação<small>Abrir, retirar e liberar caixas vazias</small></button>');$('nav').insertAdjacentHTML('beforeend',`<button onclick="go('Transferir caixas')">↔ &nbsp; Transferir caixas</button><button onclick="go('Separação')">▣ &nbsp; Separação</button>`);if(view==='Transferir caixas'){$('app').insertAdjacentHTML('beforeend',transferPage());previewTransfer()}if(view==='Separação')$('app').insertAdjacentHTML('beforeend',pickingPage())};
const warehousePreviousHistory=mediumHistory;
mediumHistory=function(id){warehousePreviousHistory(id);const entries=warehouseMovements.filter(m=>m.boxId===id||m.items?.some(i=>i.id===id));$('fields').insertAdjacentHTML('beforeend','<h2>Transferências e retiradas</h2>'+entries.map(m=>{const item=m.items?.find(i=>i.id===id);return `<div class="row"><div><strong>${m.id} · ${m.type}</strong><small>${item?`${esc(locations[item.from])} → ${esc(locations[item.to])} · ${item.qty} pops`:`${m.qty} pops retirados · saldo ${m.after} · ${esc(m.reason)}`}</small></div></div>`}).join(''))};
render();
